?><section class="tx-workspace" id="tx-records"><?php ui_page_heading($title,['records'=>'Find recorded activity across the accounting records.','cdb'=>'Review recorded payments, newest first.','crb'=>'Review recorded money received, newest first.'][$view],$actions); ?>
<form class="tx-filters" id="tx-filters" method="get" action="financial_records.php" novalidate>
<input type="hidden" name="view" value="<?= ui_escape($view) ?>"><input type="hidden" name="sort" value="<?= ui_escape($criteria['sort']) ?>">
<div class="tx-filter-grid"><?php foreach(['from'=>'From','to'=>'To'] as $name=>$label):?><label><?= $label ?><input type="date" name="<?= $name ?>" value="<?= ui_escape($criteria[$name]) ?>"></label><?php endforeach;?>
<?php if($view==='records'):?><label>Transaction type<select name="book"><option value="">All types</option><?php foreach(['CDB'=>'Payments','CRB'=>'Money Received','GJ'=>'General Journal / Reversals'] as $value=>$label):?><option value="<?= $value ?>"<?= ($criteria['book']??'')===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><?php endif;?>
