<?php if($view!=='records'):?><label>Account<select name="account_id"><option value="">All accounts</option><?php foreach($accounts as $a):?><option value="<?= ui_escape($a['CategoryID']) ?>"<?= (string)$criteria['account_id']===(string)$a['CategoryID']?' selected':'' ?>><?= ui_escape(($a['Account_Code']?:'').' '.$a['Name']) ?></option><?php endforeach;?></select></label><?php endif;?>
</div><label class="tx-search">Search transactions<input type="search" name="search" maxlength="1000" placeholder="Journal number, reference, party, purpose or project" value="<?= ui_escape($criteria['search']) ?>"></label>
