<label>Account type<select name="type"><option value="">All account types</option><?php foreach(ACCOUNTING_TYPES as $type):?><option<?= $criteria['type']===$type?' selected':'' ?>><?= $type ?></option><?php endforeach;?></select></label></div></details>
<div class="tx-toolbar"><div class="tx-actions"><button class="ui-button ui-button-primary" type="submit">Apply</button><a class="ui-button" href="financial_records.php?view=<?= $view ?>&amp;reset=1">Clear</a></div><p id="tx-draft-notice" role="status"></p></div></form>
