<div class="tx-table-region" role="region" aria-label="Matching transactions" tabindex="0"><table class="tx-table" id="tx-table"><caption class="tx-sr-only">One recorded transaction per row</caption><thead><tr><?php foreach(['Date','Type','Reference','Party','Purpose','Project','Amount / Summary','View'] as $n=>$label):?><th scope="col"><?php if($n<5):?><button type="button" data-tx-sort="<?= $n ?>"><?= $label ?><span aria-hidden="true"> ↕</span></button><?php else:?><?= $label ?><?php endif;?></th><?php endforeach;?></tr></thead><tbody id="tx-rows"></tbody></table></div>
<nav class="tx-pagination" aria-label="Transaction pages"><button type="button" class="ui-button" id="tx-previous">Previous</button><span id="tx-page" role="status"></span><button type="button" class="ui-button" id="tx-next">Next</button></nav>
