<dialog id="tx-dialog" aria-labelledby="tx-dialog-title"><header class="tx-toolbar"><h2 id="tx-dialog-title"></h2><button type="button" class="ui-button" id="tx-dialog-close" aria-label="Close transaction preview">Close</button></header><div id="tx-dialog-content"></div></dialog>
</section><script type="application/json" id="tx-data"><?= json_encode(['model'=>$model,'role'=>$_SESSION['Role']??''],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR|JSON_INVALID_UTF8_SUBSTITUTE) ?></script><?php layout_end('<script src="assets/js/transaction_records.js?v='.filemtime(__DIR__.'/../assets/js/transaction_records.js').'" defer></script>'); ?>
